from pathlib import Path
from PIL import Image,ImageDraw
import numpy as np,json,hashlib,shutil
repo=Path('/workspace/agent-sprite-forge');root=repo/'src/pixel-looks/mecha-candidate-2';base=Image.open(root/'v001/mecha-final-1x.png');prior=Image.open(root/'actions/clenched-fists/v001/mecha-clenched-fists-1x.png');pal=base.getpalette();assert prior.getpalette()==pal
b=np.array(base);p=np.array(prior);mask=np.zeros(b.shape,dtype=bool);mask[27:82,16:57]=True
f=b.copy();f[mask]=p[mask];assert np.array_equal(f[~mask],b[~mask]);assert np.array_equal(f[:,72:],b[:,72:])
out=Path('/workspace/work/mecha-right-fist-v001/deliverables');out.mkdir(exist_ok=False)
im=Image.fromarray(f);im.putpalette(pal);im.save(out/'mecha-right-fist-1x.png',bits=4);im.save(out/'mecha-right-fist.bmp');im.resize((864,672),Image.Resampling.NEAREST).save(out/'mecha-right-fist-6x.png',bits=4)
page=Image.new('RGB',(1152,500),tuple(pal[:3]));d=ImageDraw.Draw(page);d.text((18,10),'Approved Candidate 2 base',fill='white');d.text((594,10),'Right fist only / left arm restored to base',fill='white');page.paste(base.convert('RGB').resize((576,448),Image.Resampling.NEAREST),(0,36));page.paste(im.convert('RGB').resize((576,448),Image.Resampling.NEAREST),(576,36));page.save(out/'base-right-fist-comparison.png')
r=Image.open(out/'mecha-right-fist-1x.png');assert r.size==(144,112) and r.getpalette()==pal and len(set(r.get_flattened_data()))==16 and 'transparency' not in r.info
assert Image.open(out/'mecha-right-fist-6x.png').convert('RGB').tobytes()==r.convert('RGB').resize((864,672),Image.Resampling.NEAREST).tobytes()
meta={'canvas':[144,112],'stored_palette_entries':16,'used_palette_entries':16,'palette_exactly_matches_base':True,'background_rgb':pal[:3],'opaque':True,'changed_arm':'mecha right, viewers left','restored_arm':'mecha left, viewers right; exact approved Candidate 2 base pixels','edited_region_xyxy_exclusive':[16,27,57,82],'pixels_outside_region_identical_to_approved_base':True,'entire_viewer_right_half_identical_to_approved_base':True,'changed_pixels_from_base':int((f!=b).sum()),'method':'exact indexed-pixel restoration/compositing from approved base and existing clenched-fist action; no additional generation','game_import_compatibility':'not verified'}
(out/'specification.json').write_text(json.dumps(meta,indent=2));(out/'report.txt').write_text('Right-fist-only correction. Anatomical right is on the viewers left. The right arm retains the existing raised clenched fist. The anatomical left arm and hand, on the viewers right, are restored pixel-for-pixel from approved Candidate 2 v001. Every pixel outside the documented right-arm region also comes directly from that approved base.\nNative 144x112, exact approved 16-entry indexed palette, all entries used, opaque teal RGB(88,120,120). Integer nearest-neighbour 6x preview and indexed BMP included. No new image generation or repository/editor source changes. No game-import compatibility claim.\n')
proc=out/'processing';proc.mkdir();shutil.copy2('/workspace/work/mecha-right-fist-v001/build.py',proc/'build.py');(out/'sha256.json').write_text(json.dumps({str(q.relative_to(out)):hashlib.sha256(q.read_bytes()).hexdigest() for q in out.rglob('*') if q.is_file()},indent=2));print(json.dumps(meta))
